import React, { useState } from 'react';
import api from '../api';

const DeterministicQR = ({ seed }) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
        hash = ((hash << 5) - hash) + seed.charCodeAt(i);
        hash |= 0;
    }
    const size = 11;
    const rects = [];
    for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
            const isCorner = (r < 3 && c < 3) || (r < 3 && c >= size - 3) || (r >= size - 3 && c < 3);
            const filled = isCorner || (Math.abs((hash * (r + 3) * (c + 7) + r * 13 + c * 17)) % 3 === 0);
            if (filled) {
                rects.push(<rect key={`${r}-${c}`} x={c * 8 + 6} y={r * 8 + 6} width="7" height="7" rx="1.2" fill="#0f172a" />);
            }
        }
    }
    return <svg viewBox="0 0 100 100" className="w-24 h-24 bg-white p-1.5 rounded-xl shadow-inner">{rects}</svg>;
};

const GateSimulator = ({ tickets, onRefreshTickets, onBuyMore, showToast }) => {
    const [gateName, setGateName] = useState('GATE-01 Main Entrance');
    const [manualToken, setManualToken] = useState('');
    const [scanState, setScanState] = useState('IDLE'); // IDLE, GRANTED, DENIED
    const [statusTitle, setStatusTitle] = useState('READY TO SCAN');
    const [statusSub, setStatusSub] = useState('Click "Scan at IoT Gate" on any ticket or paste a QR hash below.');
    const [armOpen, setArmOpen] = useState(false);
    const [apiLog, setApiLog] = useState(JSON.stringify({
        endpoint: 'POST /api/v1/tickets/validate',
        device: 'RPI4-GATE-01',
        status: 'IDLE_LISTENING_UART'
    }, null, 2));

    const triggerScan = async (qrHash) => {
        try {
            const res = await api.post('/tickets/validate', { qrHash, gateName });
            setScanState('GRANTED');
            setStatusTitle('ACCESS GRANTED — GATE UNLOCKED');
            setStatusSub(`${res.data.seatLabel} (${res.data.tier}) marked USED at ${res.data.scannedAt}.`);
            setArmOpen(true);
            setTimeout(() => setArmOpen(false), 3000);

            setApiLog(JSON.stringify({
                request: { method: 'POST', path: '/api/v1/tickets/validate', qrHash, gate: gateName },
                response: { httpStatus: 200, ...res.data, gpioPin18: 'HIGH_3000MS' }
            }, null, 2));

            showToast(`Gate Unlocked for ${qrHash}!`, 'success');
            onRefreshTickets();
        } catch (err) {
            const errData = err.response?.data || { code: 'ERROR', message: 'Validation failed' };
            setScanState('DENIED');
            setStatusTitle(`ACCESS DENIED — ${errData.code || 'REJECTED'}`);
            setStatusSub(errData.message);

            setApiLog(JSON.stringify({
                request: { method: 'POST', path: '/api/v1/tickets/validate', qrHash, gate: gateName },
                response: { httpStatus: err.response?.status || 409, ...errData }
            }, null, 2));

            showToast(errData.message, 'error');
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-900 border border-slate-800 rounded-2xl p-5">
                <div>
                    <h2 className="text-xl font-extrabold text-white">Digital QR Wallet &amp; Physical IoT Gate Simulator</h2>
                    <p className="text-sm text-slate-400">Scan an <span className="text-emerald-400 font-semibold">ACTIVE</span> ticket to unlock the turnstile, or scan a <span className="text-rose-400 font-semibold">USED</span> ticket to test anti-replay protection.</p>
                </div>
                <button onClick={onBuyMore} className="px-4 py-2.5 rounded-xl bg-cyan-500 hover:bg-cyan-400 text-slate-950 font-bold text-xs sm:text-sm transition">
                    + Buy More Tickets
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                <div className="lg:col-span-7 space-y-4">
                    <div className="flex items-center justify-between">
                        <h3 className="text-sm font-bold uppercase tracking-wider text-slate-400">Your Issued QR Tickets ({tickets.length})</h3>
                        <span className="text-xs font-mono text-slate-500">Algorithm: HMAC-SHA256</span>
                    </div>

                    {tickets.length === 0 ? (
                        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 text-center text-slate-400 text-sm">
                            No tickets in your wallet yet. Switch to the Event Catalog to book seats!
                        </div>
                    ) : (
                        tickets.map(tkt => {
                            const isActive = tkt.status === 'ACTIVE';
                            return (
                                <div key={tkt.id} className={`ticket-cutout bg-slate-900 border ${isActive ? 'border-slate-700/90' : 'border-slate-800 opacity-85'} rounded-2xl p-5 flex flex-col sm:flex-row items-center justify-between gap-5 shadow-lg`}>
                                    <div className="space-y-2 flex-1">
                                        <div className="flex flex-wrap items-center gap-2">
                                            {isActive ? (
                                                <span className="px-2.5 py-1 rounded-full text-xs font-mono font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">● ACTIVE</span>
                                            ) : (
                                                <span className="px-2.5 py-1 rounded-full text-xs font-mono font-bold bg-rose-500/20 text-rose-300 border border-rose-500/40">✕ USED ({tkt.scannedAt})</span>
                                            )}
                                            <span className="font-mono text-xs text-slate-400">{tkt.id}</span>
                                        </div>
                                        <h4 className="text-lg font-extrabold text-white">{tkt.eventTitle}</h4>
                                        <p className="text-xs text-slate-300">📍 {tkt.venue} • 🗓️ {tkt.date}</p>
                                        <div className="pt-1 flex flex-wrap items-center gap-3 text-xs font-mono">
                                            <span className="px-2.5 py-1 rounded-lg bg-slate-950 border border-slate-800 text-cyan-300 font-semibold">{tkt.tier}</span>
                                            <span className="px-2.5 py-1 rounded-lg bg-slate-950 border border-slate-800 text-amber-300 font-semibold">{tkt.seat}</span>
                                        </div>
                                        {!isActive && <p className="text-[11px] font-mono text-slate-400 pt-1">Validated at: {tkt.scannedBy}</p>}
                                    </div>

                                    <div className="flex flex-col items-center gap-2.5 shrink-0 border-t sm:border-t-0 sm:border-l border-dashed border-slate-700 pt-4 sm:pt-0 sm:pl-5 w-full sm:w-auto">
                                        <DeterministicQR seed={tkt.id} />
                                        <button onClick={() => triggerScan(tkt.id)} className={`w-full px-3.5 py-2 rounded-xl font-bold text-xs transition ${isActive ? 'bg-emerald-500 hover:bg-emerald-400 text-slate-950 shadow-md shadow-emerald-500/20' : 'bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 border border-rose-500/40'}`}>
                                            📡 {isActive ? 'Scan at IoT Gate' : 'Test Duplicate Scan'}
                                        </button>
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>

                {/* Edge Gate Terminal */}
                <div className="lg:col-span-5 sticky top-24 bg-slate-900 border-2 border-slate-800 rounded-2xl overflow-hidden shadow-2xl">
                    <div className="bg-slate-950 px-5 py-3.5 border-b border-slate-800 flex items-center justify-between">
                        <div className="flex items-center gap-2.5">
                            <span className="w-2.5 h-2.5 rounded-full bg-cyan-400 animate-pulse"></span>
                            <span className="font-mono text-xs font-bold text-slate-200">EDGE-UNIT: RPI4-GATE</span>
                        </div>
                        <select value={gateName} onChange={(e) => setGateName(e.target.value)} className="bg-slate-900 border border-slate-700 text-xs font-mono text-cyan-300 rounded-lg px-2 py-1 focus:outline-none">
                            <option value="GATE-01 Main Entrance">GATE-01 Main Entrance</option>
                            <option value="GATE-02 VIP North">GATE-02 VIP North</option>
                            <option value="GATE-03 East Wing">GATE-03 East Wing</option>
                        </select>
                    </div>

                    <div className="p-5 space-y-5">
                        <div className={`rounded-2xl p-5 text-center space-y-2 transition-all ${scanState === 'GRANTED' ? 'bg-emerald-950/60 border-2 border-emerald-500 led-green' : scanState === 'DENIED' ? 'bg-rose-950/60 border-2 border-rose-500 led-red' : 'bg-slate-950 border border-cyan-500/30'}`}>
                            <div className={`w-14 h-14 mx-auto rounded-full flex items-center justify-center font-extrabold text-2xl ${scanState === 'GRANTED' ? 'bg-emerald-500 text-slate-950' : scanState === 'DENIED' ? 'bg-rose-500 text-white' : 'bg-cyan-500/20 border-2 border-cyan-400 text-cyan-300'}`}>
                                {scanState === 'GRANTED' ? '✓' : scanState === 'DENIED' ? '✕' : '📡'}
                            </div>
                            <h4 className={`font-mono font-extrabold text-base ${scanState === 'GRANTED' ? 'text-emerald-400' : scanState === 'DENIED' ? 'text-rose-400' : 'text-cyan-300'}`}>{statusTitle}</h4>
                            <p className="text-xs text-slate-400">{statusSub}</p>
                        </div>

                        <div className="bg-slate-950/80 border border-slate-800 rounded-xl p-4">
                            <div className="flex items-center justify-between text-[11px] font-mono text-slate-400 mb-3">
                                <span>GPIO RELAY PIN 18 (ACTUATOR)</span>
                                <span className={`font-bold ${armOpen ? 'text-emerald-400' : 'text-amber-400'}`}>{armOpen ? 'UNLOCKED (3.0s)' : 'LOCKED'}</span>
                            </div>
                            <div className="relative h-14 bg-slate-900 rounded-lg border border-slate-800 flex items-center px-4 overflow-hidden">
                                <div className="w-8 h-10 rounded bg-slate-700 border border-slate-600 flex items-center justify-center text-[10px] font-mono font-bold text-slate-300 z-10">HUB</div>
                                <div className={`turnstile-arm h-3 w-48 rounded-r-full ml-1 shadow-lg ${armOpen ? 'turnstile-open bg-gradient-to-r from-emerald-400 to-cyan-400' : 'bg-gradient-to-r from-amber-500 to-rose-500'}`}></div>
                                <span className="ml-auto text-[10px] font-mono text-slate-500">WALKWAY</span>
                            </div>
                        </div>

                        <div className="flex gap-2">
                            <input type="text" value={manualToken} onChange={(e) => setManualToken(e.target.value)} placeholder="Paste QR token (e.g., TKT-AUR-8821)..." className="flex-1 px-3 py-2 rounded-xl bg-slate-950 border border-slate-700 text-xs font-mono text-white placeholder-slate-500 focus:outline-none focus:border-cyan-500" />
                            <button onClick={() => manualToken.trim() && triggerScan(manualToken.trim().toUpperCase())} className="px-4 py-2 rounded-xl bg-cyan-500 hover:bg-cyan-400 text-slate-950 font-bold text-xs transition">
                                Validate
                            </button>
                        </div>

                        <pre className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[11px] font-mono text-slate-300 overflow-x-auto max-h-44 leading-relaxed">
              {apiLog}
            </pre>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default GateSimulator;
